import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        mark = 0
    else:
        mark = int(data[0])
    if mark >= 90:
        grade = "A"
    elif mark >= 75:
        grade = "B"
    elif mark >= 50:
        grade = "C"
    else:
        grade = "Fail"
    print(f"Grade: {grade}")

if __name__ == "__main__":
    main()
